"use client";
import Component from "../smoothui/ProductCard";
import { useState } from "react";
import { DemoFrame } from "../shared/DemoFrame";

export default function Demo() {
  const [message, setMessage] = useState("");
  return (
    <DemoFrame hint={message} className="p-4 gap-2">
      <Component
        className="w-52"
        image="/media/art-02.svg"
        title="Terra — Art print"
        price={48}
        originalPrice={65}
        rating={4.9}
        badge="Edition 02"
        onAddToCart={() => setMessage("Art print added to your demo cart.")}
        onWishlist={() => setMessage("Saved to your demo wishlist.")}
      />
    </DemoFrame>
  );
}

/** Example and adapters: Copyright (c) 2026 NikroZorkin. MIT; licenses/elements.txt. */
import type { ReactNode } from "react";

/** Layout for this example only. The component itself has no catalog dependency. */
export function DemoFrame({
  children,
  className = "",
  hint,
}: {
  children: ReactNode;
  className?: string;
  hint?: string;
}) {
  return (
    <div
      className={`relative flex min-h-[420px] w-full flex-col items-center justify-center gap-7 overflow-hidden p-8 ${className}`}
    >
      {children}
      {hint && (
        <p className="text-center text-xs text-muted-foreground" role="status">
          {hint}
        </p>
      )}
    </div>
  );
}

@import "tailwindcss" source(none);
@source "./";
@custom-variant dark (&:where(.dark, .dark *));

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--background);
  --color-card-foreground: var(--foreground);
  --color-popover: var(--background);
  --color-popover-foreground: var(--foreground);
  --color-primary: var(--foreground);
  --color-primary-foreground: var(--background);
  --color-secondary: var(--muted);
  --color-secondary-foreground: var(--foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--muted);
  --color-accent-foreground: var(--foreground);
  --color-destructive: #ef4444;
  --color-border: var(--border);
  --color-input: var(--border);
